+    }
+
+    @Override
+    public RegisterArray getCallerSaveRegisters() {
+        return getAllocatableRegisters();
+    }
+
+    @Override
+    public boolean areAllAllocatableRegistersCallerSaved() {
+        return true;
+    }
+
+    @Override
+    public RegisterAttributes[] getAttributesMap() {
